import{_ as a,I as t,g as o,j as r}from"./chunks/framework.CjoWWfVe.js";const m=JSON.parse('{"title":"Implemented Features & Roadmap","description":"Current status of the OmniCraft ERP project and the development roadmap.","frontmatter":{"title":"Implemented Features & Roadmap","description":"Current status of the OmniCraft ERP project and the development roadmap.","order":4},"headers":[],"relativePath":"docs/roadmap.md","filePath":"docs/roadmap.md"}'),s={name:"docs/roadmap.md"};function n(i,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🚀-implemented-features-roadmap" tabindex="-1">🚀 Implemented Features &amp; Roadmap <a class="header-anchor" href="#🚀-implemented-features-roadmap" aria-label="Permalink to &quot;🚀 Implemented Features &amp; Roadmap&quot;">​</a></h1><p>OmniCraft ERP is an actively developing product. We regularly release updates based on our own hands-on crafting experience and feedback from our users. On this page, you can see what is already working stably and which features are currently under development.</p><h2 id="✅-current-status-stable-core-version-1-0-x" tabindex="-1">✅ Current Status: Stable Core (Version 1.0.x) <a class="header-anchor" href="#✅-current-status-stable-core-version-1-0-x" aria-label="Permalink to &quot;✅ Current Status: Stable Core (Version 1.0.x)&quot;">​</a></h2><p>At this moment, the <strong>Core Production Pipeline</strong> is fully implemented and polished. The standard version of the software allows you to maintain full management accounting for a micro-enterprise:</p><ul><li><strong>Workshop Assets:</strong> Smart equipment depreciation and calculation of your workshop&#39;s residual value.</li><li><strong>Materials Stock (MAC):</strong> Batch inventory accounting with unbiased, proportional allocation of shipping costs to material cost price.</li><li><strong>Calculator:</strong> Recipe constructor that factors in master labor rates and overhead norms.</li><li><strong>Production:</strong> Dynamic workbench with smart cascade calculations of material reserves (FIFO queue).</li><li><strong>Finished Goods:</strong> A catalog of completed items in stock, managed via FIFO batches to preserve historical cost accuracy.</li><li><strong>Sales:</strong> Sales channels management, custom markups, and a POS terminal that handles shipping costs (whether paid by the client or the workshop).</li><li><strong>Finance:</strong> Global management balance sheet (Capital), cash flow ledger (Cash Flow), and advanced analytical charts (Financial Pulse, Break-Even Point).</li><li><strong>Security &amp; Backups:</strong> Rotational GFS backups, WAL database journaling, and protection against data loss due to power failures.</li></ul><p>All these features are available under the <a href="./licenses">Standard License</a>.</p><hr><h2 id="🔮-under-development-pro-mode-ecosystem-roadmap" tabindex="-1">🔮 Under Development: PRO Mode &amp; Ecosystem (Roadmap) <a class="header-anchor" href="#🔮-under-development-pro-mode-ecosystem-roadmap" aria-label="Permalink to &quot;🔮 Under Development: PRO Mode &amp; Ecosystem (Roadmap)&quot;">​</a></h2><p>We have already established the fundamental architecture for the following major updates, which will be included in the <strong>PRO License</strong>.</p><h3 id="_1-multi-workspaces" tabindex="-1">1. Multi-Workspaces <a class="header-anchor" href="#_1-multi-workspaces" aria-label="Permalink to &quot;1. Multi-Workspaces&quot;">​</a></h3><p>The ability to create independent, isolated databases within a single application.</p><ul><li><em>Why is this useful?</em> If you run several different business lines (for example, a physical leather workshop and a digital store selling PDF patterns on Etsy/Shopify), you can manage them in separate workspaces with different currencies, markups, and inventory, switching between them instantly via the sidebar.</li></ul><h3 id="_2-my-capital-global-tab-personal-finance" tabindex="-1">2. &quot;My Capital&quot; Global Tab (Personal Finance) <a class="header-anchor" href="#_2-my-capital-global-tab-personal-finance" aria-label="Permalink to &quot;2. &quot;My Capital&quot; Global Tab (Personal Finance)&quot;">​</a></h3><p>A revolutionary, low-friction approach to personal finance tracking.</p><ul><li>You will simply enter the current balances of your bank cards and major assets outside of the business (house, car).</li><li>The program will automatically consolidate net profits from all your workspaces, compare them to the actual growth of your capital in accounts, and <strong>automatically calculate your daily life expenses</strong>. No more tedious logging of every coffee or grocery receipt.</li></ul><h3 id="_3-global-add-on-modules-ecosystem" tabindex="-1">3. Global Add-on Modules (Ecosystem) <a class="header-anchor" href="#_3-global-add-on-modules-ecosystem" aria-label="Permalink to &quot;3. Global Add-on Modules (Ecosystem)&quot;">​</a></h3><p>Niche tools that can be connected as add-ons. These modules are &quot;global&quot; and work across all workspaces.</p><ul><li><strong>Patterns &amp; Templates Module:</strong> Cataloging of digital/physical templates, cutting area calculations, and attachment of vector files or blueprints.</li><li><strong>Services Module:</strong> Time tracking, custom repairs, and bespoke custom orders without a rigid finished goods warehouse.</li></ul><blockquote><p><strong>Automatic Updates</strong> The program features a built-in version check. Upon launch, it will notify you of any new updates or features and provide a download link. Your local databases will be migrated automatically and seamlessly.</p></blockquote>',20)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
